"""Dashboard templates; the app uses the supplied SMS Forwarder reference."""
from pathlib import Path

LOGIN_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f7f7f8"><title>Sign in · SMS Forwarder</title><link rel="manifest" href="/manifest.webmanifest"><link rel="icon" type="image/svg+xml" href="/icon.svg?v=2"><link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png?v=2"><style>
:root{--w:#fff;--g:#f7f7f8;--i:#1d1d1f;--m:#6e6e73;--l:#d2d2d7;--b:#002fa7;--bs:#eef2ff}*{box-sizing:border-box}html,body{min-height:100%;background:var(--g)}body{margin:0;color:var(--i);font:16px/1.45 -apple-system,BlinkMacSystemFont,"Helvetica Neue",Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased}.signin{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(340px,.8fr);width:min(1060px,calc(100% - 40px));min-height:650px;margin:clamp(20px,7vh,80px) auto;border:1px solid var(--l);background:var(--w)}.statement{position:relative;display:flex;flex-direction:column;justify-content:space-between;padding:42px;border-right:1px solid var(--l);overflow:hidden}.wordmark{display:flex;align-items:center;gap:11px;font-size:.85rem;font-weight:650}.mark{display:grid;place-items:center;width:38px;height:38px;background:var(--b);color:#fff;font-size:.72rem;font-weight:750}.statement h1{position:relative;z-index:1;margin:0;font-size:clamp(3.3rem,7vw,6.4rem);line-height:.88;letter-spacing:-.075em}.signal{position:absolute;right:-10px;top:88px;display:flex;align-items:flex-end;gap:10px;height:260px;opacity:.075}.signal i{width:46px;background:var(--b)}.signal i:nth-child(1){height:25%}.signal i:nth-child(2){height:50%}.signal i:nth-child(3){height:75%}.signal i:nth-child(4){height:100%}.panel{display:flex;flex-direction:column;justify-content:center;padding:clamp(32px,5vw,64px)}.panel h2{margin:0;font-size:2rem;letter-spacing:-.045em}.panel>p{margin:10px 0 28px;color:var(--m);font-size:.92rem}.error{padding:12px 14px;border-left:3px solid var(--b);background:var(--bs);color:#001f73;font-weight:600}label{display:block;margin:17px 0 7px;font-size:.78rem;font-weight:650}input[type=text],input[type=password]{width:100%;height:48px;padding:0 13px;border:1px solid var(--l);border-radius:10px;background:#fff;color:var(--i);font:inherit;outline:0}input:focus{border-color:var(--b);box-shadow:0 0 0 3px rgba(0,47,167,.12)}.remember{display:flex;align-items:center;gap:10px;margin:18px 0 24px;font-size:.86rem}.remember input{width:18px;height:18px;accent-color:var(--b)}button{width:100%;min-height:48px;border:0;border-radius:10px;background:var(--b);color:#fff;font:650 1rem/1.2 inherit;cursor:pointer}@media(max-width:720px){.signin{display:block;width:calc(100% - 28px);min-height:0;margin:max(14px,env(safe-area-inset-top)) auto}.statement{min-height:310px;padding:28px;border-right:0;border-bottom:1px solid var(--l)}.statement h1{font-size:3.5rem}.signal{top:70px;height:170px}.signal i{width:32px}.panel{padding:30px 26px 36px}}</style></head><body><main class="signin"><section class="statement"><div class="wordmark"><span class="mark">4G</span>DJI Messages</div><div class="signal" aria-hidden="true"><i></i><i></i><i></i><i></i></div><h1>Your number.<br>Anywhere.</h1></section><section class="panel"><h2>Welcome back</h2><p>Sign in to messages and gateway controls.</p>@@ERROR@@<form method="post" action="/login"><input type="hidden" name="csrf" value="@@CSRF@@"><input type="hidden" name="next" value="@@NEXT@@"><label for="username">Username</label><input id="username" name="username" type="text" autocomplete="username" required autofocus><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required><label class="remember"><input name="remember" type="checkbox" value="yes" checked>Keep me signed in for 30 days</label><button type="submit">Sign in</button></form></section></main></body></html>'''

